sheet.css:
.pk{--paper:#faf7f2;--ink:#141414;--grey:#6a655e;--rule:#ddd8d0;--accent:#9b2226;
  background:var(--paper);color:var(--ink);
  font:400 17px/1.6 Georgia,'Iowan Old Style','Times New Roman',serif}
[data-theme=dark].pk,[data-theme=dark] .pk{--paper:#17150f;--ink:#ece7dd;--grey:#a39c90;--rule:#3a352c}
.stage.pk{--page:var(--paper);background:var(--paper)}
.pk h3,.pk h4{margin:0;font-weight:700;letter-spacing:-.02em;line-height:.95}
.pk p{margin:0}
.kicker{font:700 11px/1 ui-sans-serif,system-ui;letter-spacing:.28em;text-transform:uppercase;
  color:var(--accent)}
.byline{font:400 13px/1.4 ui-sans-serif,system-ui;color:var(--grey)}
.pull{border-top:2px solid var(--ink);border-bottom:2px solid var(--ink);padding:14px 0;
  font-style:italic;font-size:21px;line-height:1.35;max-width:36ch}
.dropcap::first-letter{float:left;font-size:3.4em;line-height:.82;padding:.04em .08em 0 0;font-weight:700}
.twocol{columns:2;column-gap:34px;column-rule:1px solid var(--rule);font-size:15px}
@media(max-width:700px){.twocol{columns:1}}
.pk-btn{font:600 14px/1 ui-sans-serif,system-ui;background:var(--ink);color:var(--paper);
  border:1px solid var(--ink);border-radius:0;padding:12px 20px;cursor:pointer}
.pk-btn:hover{opacity:.85}
.pk-btn:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.pk-btn.sec{background:transparent;color:var(--ink);border-color:var(--rule)}
.pk-btn[disabled]{opacity:.4;cursor:not-allowed}
.f-hover{opacity:.85}
.f-focus{outline:2px solid var(--accent);outline-offset:3px}
.pk-field{width:100%;background:transparent;color:var(--ink);border:0;border-bottom:1px solid var(--ink);
  border-radius:0;padding:8px 0;font:400 17px/1.4 inherit}
.pk-field:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.pk-label{display:block;font:700 11px/1 ui-sans-serif,system-ui;letter-spacing:.24em;
  text-transform:uppercase;color:var(--grey);margin-bottom:7px}
.pk-err{margin-top:8px;font-style:italic;font-size:15px}
.pk-err .r{display:block;height:2px;background:var(--accent);width:100%;margin-bottom:7px}
.pk-nav{border-bottom:2px solid var(--ink);padding-bottom:10px}
.pk-nav .mast{font-weight:700;font-size:26px;letter-spacing:-.02em}
.pk-nav .row{display:flex;gap:18px;margin-top:8px}
.pk-nav a{color:var(--grey);text-decoration:none;font:600 11px/1 ui-sans-serif,system-ui;
  letter-spacing:.2em;text-transform:uppercase;display:inline-block;padding:7px 0;min-height:25px}
.pk-nav a[aria-current]{color:var(--ink)}
.pk-nav .sp{flex:1}
table.pk-t{width:100%;border-collapse:collapse;font-size:15px;font-variant-numeric:tabular-nums}
table.pk-t th{text-align:left;font:700 10px/1 ui-sans-serif,system-ui;letter-spacing:.22em;
  text-transform:uppercase;color:var(--grey);padding:0 8px 10px 0;border-bottom:1px solid var(--ink)}
table.pk-t td{padding:12px 8px 12px 0;border-bottom:1px solid var(--rule)}
.pk-scrim{background:rgba(20,15,8,.6);padding:36px 18px;display:flex;justify-content:center}
.pk-dialog{background:var(--paper);padding:24px;max-width:400px;width:100%;border-top:4px solid var(--ink)}
.pk-empty{border-top:2px solid var(--ink);padding:26px 0}
.pk-skel{height:12px;background:var(--rule);margin-bottom:11px}
.swatch{border:1px solid var(--rule,#ddd8d0);height:54px}

page.css:
/* Widening the page widened every uncapped paragraph with it. In a reading-led
   pack the measure is a PACK RULE, not a per-element decision — so it is set once
   here and individual elements only ever tighten it. */
main p{max-width:68ch}
.s{padding-block:clamp(40px,6vw,86px)}
.s + .s{border-top:1px solid var(--rule)}
/* Gate 2.5: a photograph is a RASTER, never CSS. This is a declared placeholder —
   flat fill, not a gradient (which the pack bans anyway), and it names itself so
   engine/audit.mjs FAILS until the real asset lands. */
.figure{background:#c9c0b2;aspect-ratio:4/5;width:100%}
.figcap{font:400 12px/1.4 ui-sans-serif,system-ui;color:var(--grey);margin-top:8px}
